#!/usr/bin/env python3
"""Builds one of NumPlay's big standalone games natively (the ones that are an app of their own on a calculator).

  build_big.py --game celeste --numplay NumPlay-main --target host --out build/celeste   (links ./build/celeste/<game>)
  build_big.py --game celeste --numplay NumPlay-main --target 3ds  --out build/celeste   (objects + numplay_objs.txt)

Each game is its own program with its own main(), an EADK platform file (plat_eadk.c) and, usually, its assets embedded
from src/data.bin by src/data.S. Their sources are every top-level src/*.c except plat_host.c (the PC test platform),
plus src/lzma/LzmaDec.c where present: the same lists their own Makefiles build. A few need more (see the table):
files of the launcher, files generated by a script of the game, C++ (Hill Climb's Box2D), or a layout of their own
(Doom). The EADK itself is port/eadk_port.c.
"""
import argparse, os, shlex, subprocess, sys
from concurrent.futures import ThreadPoolExecutor

HERE = os.path.dirname(os.path.abspath(__file__))
PORT = os.path.join(os.path.dirname(HERE), "port")
sys.path.insert(0, HERE)
import np_patches

XL = ["-DEPSILON_XL=1"]  # the games' own builds for the big calculators pass this; harmless here
LAUNCHER_GFX = ["launcher/src/gfx.c", "launcher/src/font_data.c", "launcher/src/xfont.c"]


def std(save, **kw):
    d = dict(save=save, heap=262144, keymap="DEFAULT", defs=list(XL))
    d.update(kw)
    return d


# id: save folder on the SD card, bytes of the spare-RAM pool the game gets, key layout (port_3ds.c), extra defines,
#     screen: "top" (the 320x240 picture centred on the top screen), "bottom" (the touch screen: games with a stylus)
#     or "scaled" (Celeste's letterboxed picture, scaled up); see port_3ds.c
TITLES = {'hollowknight': 'Hollow Knight', 'celeste': 'Celeste', 'championisland': 'Champion Island Games', 'finalearth2': 'The Final Earth 2', 'numpowder': 'NumPowder', 'undertale': 'Undertale', 'subway': 'Subway Surfers', 'fnaf': "Five Nights at Freddy's", 'doom': 'Doom', 'isaac': 'The Binding of Isaac', 'hillclimb': 'Hill Climb Racing', 'pvz': 'Plants vs. Zombies', 'sonic': 'Sonic the Hedgehog', 'cookieclicker': 'Cookie Clicker', 'leveldevil': 'Level Devil', 'jetpackjoyride': 'Jetpack Joyride', 'stickmanhook': 'Stickman Hook', 'donkeykong': 'Donkey Kong', 'dune': 'Dune', 'monkeymart': 'Monkey Mart', 'tombofthemask': 'Tomb of the Mask', 'uno': 'Uno', 'fnf': "Friday Night Funkin'"}

GAMES = {
    "hollowknight":   dict(save="HollowKnight", heap=262144, keymap="ACTION", screen="top"),
    "celeste":        dict(save="Celeste", heap=262144, keymap="CELESTE", screen="scaled"),
    "championisland": dict(save="ChampionIsland", heap=262144, keymap="CHAMPION", screen="top"),
    "finalearth2":    dict(save="FinalEarth2", heap=262144, keymap="BUILDER", screen="bottom"),
    "numpowder":      dict(save="NumPowder", heap=524288, keymap="BUILDER", screen="bottom"),
    # ---- NumPlay 1.16
    "undertale":      std("Undertale", keymap="UNDERTALE", screen="top"),
    "subway":         std("SubwaySurfers", keymap="SUBWAY", heap=1048576, screen="top"),
    "fnaf":           std("FNaF", keymap="FNAF", screen="top"),
    "doom":           std("Doom", keymap="DOOM", screen="top", kind="doom", defs=XL + ["-fwrapv", "-DNDEBUG", "-DNP_NATIVE=1"]),
    "isaac":          std("Isaac", keymap="ISAAC", screen="top"),
    "hillclimb":      std("HillClimb", keymap="ARCADE", screen="top", cxx="hillclimb"),
    "pvz":            std("PlantsVsZombies", keymap="DEFAULT", screen="bottom", extra_src=["launcher/src/inflate.c"], inc=["launcher/src"]),
    "sonic":          std("Sonic", keymap="ARCADE", screen="top", defs=XL + ["-fwrapv"]),
    "cookieclicker":  std("CookieClicker", keymap="COOKIE", screen="bottom"),
    "leveldevil":     std("LevelDevil", keymap="ARCADE", screen="top", extra_src=LAUNCHER_GFX, inc=["launcher/src"], gen="leveldevil"),
    "jetpackjoyride": std("JetpackJoyride", keymap="ARCADE", screen="top", extra_src=LAUNCHER_GFX, inc=["launcher/src"]),
    "stickmanhook":   std("StickmanHook", keymap="ARCADE", screen="top"),
    "donkeykong":     std("DonkeyKong", keymap="ARCADE", screen="top", extra_src=LAUNCHER_GFX, inc=["launcher/src"]),
    "dune":           std("Dune", keymap="ARCADE", screen="top"),
    "monkeymart":     std("MonkeyMart", keymap="ARCADE", screen="top"),
    "tombofthemask":  std("TombOfTheMask", keymap="ARCADE", screen="top"),
    "uno":            std("Uno", keymap="ARCADE", screen="top", extra_src=LAUNCHER_GFX, inc=["launcher/src"]),
    "fnf":            std("FNF", keymap="FNF", screen="top", extra_src=LAUNCHER_GFX, inc=["launcher/src"], gen="fnf"),
}


def sh(cmd, **kw):
    r = subprocess.run(cmd, capture_output=True, text=True, **kw)
    if r.returncode:
        sys.exit("FAILED: %s\n%s%s" % (" ".join(cmd), r.stdout, r.stderr))
    return r.stdout


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--game", required=True, choices=sorted(GAMES))
    ap.add_argument("--numplay", required=True)
    ap.add_argument("--target", choices=["host", "3ds"], required=True)
    ap.add_argument("--out", required=True)
    ap.add_argument("--opt", default="-O2")
    a = ap.parse_args()
    cfg = GAMES[a.game]
    np_dir = os.path.abspath(a.numplay)
    print("patches:", np_patches.apply(np_dir) or "already applied")
    gdir = os.path.join(np_dir, "games", a.game)
    src = os.path.join(gdir, "src")
    out = os.path.abspath(a.out)
    os.makedirs(out, exist_ok=True)
    gen = os.path.join(out, "gen")

    if a.target == "host":
        pre, arch = "", []
        cc, cxx = os.environ.get("CC", "gcc"), os.environ.get("CXX", "g++")
    else:
        pre = os.environ.get("CROSS", "arm-none-eabi-")
        cc, cxx = pre + "gcc", pre + "g++"
        arch = ["-march=armv6k", "-mtune=mpcore", "-mfpu=vfp", "-mfloat-abi=hard", "-mtp=soft", "-mword-relocations",
                "-ffunction-sections", "-fdata-sections", "-D__3DS__", "-DNP_KEYMAP_" + cfg["keymap"],
                '-DNP_SAVE_DIR="%s"' % cfg["save"], '-DNP_GAME_TITLE="%s"' % TITLES[a.game]]
        if cfg["screen"] in ("top", "scaled"):
            arch.append("-DNP_GAME_ON_TOP")
        if cfg["screen"] == "scaled":
            arch.append("-DNP_TOP_SCALE")

    # files the game's own scripts make (their Makefiles run them the same way)
    extra_inc = []
    extra_c = []
    if cfg.get("gen") == "leveldevil":  # python3 tools/rooms.py <dir>: writes rooms.inc
        os.makedirs(gen, exist_ok=True)
        sh([sys.executable, "tools/rooms.py", gen], cwd=gdir)
        extra_inc.append(gen)
    if cfg.get("gen") == "fnf":  # the Funkin' Crew's files, fetched at a pinned commit, then packed into data.c
        ref = os.path.join(out, "ref")
        os.makedirs(gen, exist_ok=True)
        sh([sys.executable, "-I", "tools/fetch.py", ref], cwd=gdir)
        sh([sys.executable, "-I", "tools/data.py", ref, gen], cwd=gdir)
        extra_inc.append(gen)
        extra_c.append(os.path.join(gen, "data.c"))

    flags = shlex.split(sh(["npx", "--yes", "--", "nwlink@1.0.0", "eadk-cflags-simulator"]))
    eadk = [f[2:] for f in flags if f.startswith("-I")][0]
    incs = ["-I" + eadk, "-I" + PORT, "-I" + src] + ["-I" + os.path.join(np_dir, i) for i in cfg.get("inc", [])] + \
           ["-I" + i for i in extra_inc]
    force = ["-include", "np_native.h"]
    common = arch + shlex.split(a.opt) + ["-w"] + incs + ["-fno-math-errno", "-fsingle-precision-constant",
              "-DNP_HEAP_BYTES=%d" % cfg["heap"]] + cfg.get("defs", []) + shlex.split(os.environ.get("NP_CPPFLAGS", ""))
    cflags = [cc] + common + force + ["-std=gnu11"]
    cxxflags = [cxx] + common + force + ["-std=gnu++11", "-fno-exceptions", "-fno-rtti", "-fno-threadsafe-statics",
                                          "-fno-use-cxa-atexit"]

    c_files, cxx_files = [], []  # (path, object name)
    if cfg.get("kind") == "doom":
        # the engine (Chocolate Doom by way of RP2040 Doom) and the calculator's side of it (src/nw)
        eng = [os.path.join("src", f) for f in sorted(os.listdir(src)) if f.endswith(".c")] + \
              [os.path.join("src/doom", f) for f in sorted(os.listdir(os.path.join(src, "doom"))) if f.endswith(".c")]
        nw = ["i_system", "i_video", "i_input", "i_sound", "saves", "main", "scan", "plat_eadk"]
        files = [f[4:] for f in eng] + ["nw/%s.c" % n for n in nw]
        cflags += ["-include", os.path.join(src, "nw/doomconf.h"), "-I" + src, "-I" + os.path.join(src, "doom"),
                   "-I" + os.path.join(src, "compat"), "-I" + os.path.join(src, "nw")]
        cxxflags += ["-std=gnu++17", "-include", os.path.join(src, "nw/doomconf.h"), "-I" + src,
                     "-I" + os.path.join(src, "doom"), "-I" + os.path.join(src, "compat"), "-I" + os.path.join(src, "nw")]
        cxx_files.append((os.path.join(src, "pd_render.cpp"), "g_pd_render"))
    else:
        files = sorted(f for f in os.listdir(src) if f.endswith(".c") and f != "plat_host.c")
        if os.path.exists(os.path.join(src, "lzma/LzmaDec.c")):
            files.append("lzma/LzmaDec.c")
    for f in files:
        c_files.append((os.path.join(src, f), "g_" + f.replace("/", "_")[:-2]))
    for f in cfg.get("extra_src", []):
        c_files.append((os.path.join(np_dir, f), "x_" + os.path.basename(f)[:-2]))
    for f in extra_c:
        c_files.append((f, "x_" + os.path.basename(f)[:-2]))
    if cfg.get("cxx") == "hillclimb":  # the vehicles on Box2D 2.2.1, in C++
        cxxflags += ["-DNDEBUG", "-I" + os.path.join(src, "box2d"), "-Wno-unused-but-set-variable"]
        cc_list = ["car.cpp"]
        for d in ("box2d/Box2D/Collision", "box2d/Box2D/Collision/Shapes", "box2d/Box2D/Common", "box2d/Box2D/Dynamics",
                  "box2d/Box2D/Dynamics/Contacts", "box2d/Box2D/Dynamics/Joints", "box2d/Box2D/Rope"):
            p = os.path.join(src, d)
            if os.path.isdir(p):
                cc_list += [os.path.join(d, f) for f in sorted(os.listdir(p)) if f.endswith(".cpp")]
        for f in cc_list:
            cxx_files.append((os.path.join(src, f), "p_" + f.replace("/", "_")[:-4]))

    jobs, objs = [], []
    for path, name in c_files:
        o = os.path.join(out, name + ".o")
        jobs.append(cflags + ["-c", path, "-o", o]), objs.append(o)
    for path, name in cxx_files:
        o = os.path.join(out, name + ".o")
        jobs.append(cxxflags + ["-c", path, "-o", o]), objs.append(o)
    for f in ("heap", "eadk_port", "port_3ds" if a.target == "3ds" else "port_host"):
        o = os.path.join(out, "port_" + f + ".o")
        jobs.append([cc] + common + force + ["-std=gnu11", "-c", os.path.join(PORT, f + ".c"), "-o", o]), objs.append(o)

    # assets: data.bin assembled into the program (no force-included header here)
    s_file, s_defs = os.path.join(src, "data.S"), []
    if cfg.get("kind") == "doom":
        s_file = os.path.join(src, "nw/data.S")
        s_defs = ['-DDOOM_WHX="%s"' % os.path.join(src, "doom1.whx"), '-DDOOM_MIP="%s"' % os.path.join(src, "doom1.mip")]
    elif os.path.exists(s_file):
        s_defs = ['-DDATA_BIN="%s"' % os.path.join(src, "data.bin")]
    if os.path.exists(s_file):
        data_o = os.path.join(out, "g_data.o")
        sh([cc] + arch + ["-c"] + s_defs + [s_file, "-o", data_o])
        objs.append(data_o)

    bad = False
    with ThreadPoolExecutor(os.cpu_count() or 4) as ex:
        for cmd, r in ex.map(lambda c: (c, subprocess.run(c, capture_output=True, text=True)), jobs):
            if r.returncode:
                bad = True
                print("FAILED", cmd[-3], "\n", r.stderr[:1500])
    if bad:
        sys.exit(1)
    open(os.path.join(out, "numplay_objs.txt"), "w").write("\n".join(objs))
    open(os.path.join(out, "link_cxx"), "w").write("1" if (cxx_files) else "")
    print("compiled %d objects (%d C, %d C++)" % (len(objs), len(c_files), len(cxx_files)))
    if a.target == "host":
        sh([cxx if cxx_files else cc, "-o", os.path.join(out, a.game)] + objs + ["-lm"])
        print("linked", os.path.join(out, a.game))


if __name__ == "__main__":
    main()
